css:
.forf-container {
    padding: 28px;
    background: #eef1f5;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #14233f;
}
.forf-header {
    background: #14233f;
    color: #f3f5f8;
    padding: 28px 32px;
    border-radius: 6px;
    border-left: 5px solid #b08a3e;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(20, 35, 63, 0.18);
}
.forf-header h1 {
    margin: 0 0 6px 0;
    font-size: 1.55rem;
    font-weight: 700;
    letter-spacing: 0.01em;
}
.forf-subtitle {
    color: #d8be83;
    font-size: 0.95rem;
    font-style: italic;
}
.forf-period-counter {
    background: #ffffff;
    border: 1px solid #d4dae3;
    border-radius: 6px;
    padding: 14px 20px;
    margin-bottom: 20px;
    font-size: 0.95rem;
    color: #4a5870;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}
.forf-period-counter .forf-round-name {
    margin-left: 16px;
    color: #14233f;
    font-weight: 700;
}
.forf-briefing {
    background: #ffffff;
    border: 1px solid #d4dae3;
    border-top: 3px solid #b08a3e;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.forf-briefing h3 {
    margin: 0 0 10px 0;
    font-size: 1.1rem;
    color: #14233f;
    font-weight: 700;
}
.forf-briefing #briefingText {
    color: #33425a;
    font-size: 0.95rem;
    line-height: 1.65;
}
.forf-briefing #briefingText strong { color: #14233f; }
.forf-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.forf-status-card {
    background: #ffffff;
    border: 1px solid #d4dae3;
    border-radius: 6px;
    padding: 18px 18px 16px;
    border-top: 3px solid #4a5870;
}
.forf-status-card:nth-child(1) { border-top-color: #2b6cb0; }
.forf-status-card:nth-child(2) { border-top-color: #2f855a; }
.forf-status-card:nth-child(3) { border-top-color: #b08a3e; }
.forf-card-hero {
    background: #14233f;
    border: 1px solid #14233f;
    border-top: 3px solid #b08a3e;
}
.forf-status-card .forf-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #6a778d;
    margin-bottom: 8px;
    font-weight: 700;
}
.forf-card-hero .forf-label { color: #d8be83; }
.forf-status-card .forf-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #14233f;
    line-height: 1.1;
}
.forf-value-hero {
    font-size: 2.6rem !important;
    color: #f3f5f8 !important;
}
.forf-controls {
    background: #ffffff;
    border: 1px solid #d4dae3;
    border-radius: 6px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.forf-controls h3 {
    margin: 0 0 16px 0;
    font-size: 1.1rem;
    color: #14233f;
    font-weight: 700;
    border-bottom: 1px solid #e4e8ee;
    padding-bottom: 10px;
}
.forf-helptext {
    background: #f6f3ea;
    border-left: 3px solid #b08a3e;
    color: #4a4126;
    padding: 12px 16px;
    border-radius: 4px;
    font-size: 0.9rem;
    line-height: 1.55;
    margin-bottom: 18px;
}
.forf-controls label {
    display: block;
    color: #4a5870;
    font-size: 0.85rem;
    font-weight: 700;
    margin: 14px 0 6px;
    letter-spacing: 0.01em;
}
.forf-controls input[type="number"],
.forf-controls input[type="text"],
.forf-controls select {
    width: 100%;
    background: #fbfcfe;
    border: 1px solid #c2c9d4;
    color: #14233f;
    border-radius: 4px;
    padding: 9px 12px;
    font-size: 0.95rem;
    font-family: inherit;
}
.forf-controls select option {
    background: #ffffff;
    color: #14233f;
}
.forf-controls input:focus,
.forf-controls select:focus {
    outline: none;
    border-color: #b08a3e;
    box-shadow: 0 0 0 3px rgba(176, 138, 62, 0.2);
}
.forf-bench {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 10px;
    margin-bottom: 14px;
}
.forf-cand {
    border: 1px solid #d4dae3;
    border-radius: 5px;
    padding: 10px 12px;
    cursor: pointer;
    background: #fbfcfe;
    transition: border-color 0.15s ease, background 0.15s ease;
    display: flex;
    gap: 10px;
    align-items: flex-start;
}
.forf-cand:hover { border-color: #b08a3e; }
.forf-cand.selected {
    border-color: #2f855a;
    background: #eef7f1;
    box-shadow: inset 0 0 0 1px #2f855a;
}
.forf-cand input[type="checkbox"] {
    width: auto;
    margin-top: 3px;
}
.forf-cand-body { flex: 1; }
.forf-cand-name { font-weight: 700; color: #14233f; font-size: 0.9rem; }
.forf-cand-meta { font-size: 0.78rem; color: #6a778d; margin-top: 2px; line-height: 1.4; }
.forf-cand-tags { margin-top: 5px; }
.forf-tag {
    display: inline-block;
    font-size: 0.68rem;
    font-weight: 700;
    padding: 1px 7px;
    border-radius: 10px;
    margin-right: 4px;
    margin-bottom: 3px;
}
.forf-tag-sen { background: #e4ecf6; color: #2b6cb0; }
.forf-tag-div { background: #e7f3ec; color: #2f855a; }
.forf-tag-risk { background: #fbeaea; color: #c0392b; }
.forf-bench-summary {
    font-size: 0.95rem;
    font-weight: 700;
    color: #14233f;
    margin-bottom: 8px;
}
.forf-bench-warn, .forf-attn-warn {
    color: #c0392b;
    font-weight: 600;
    margin-left: 10px;
    font-size: 0.85rem;
}
.forf-dispute {
    border: 1px solid #d4dae3;
    border-radius: 6px;
    padding: 14px 18px;
    margin-bottom: 16px;
    background: #fafbfd;
}
.forf-dispute-title {
    font-weight: 700;
    color: #14233f;
    font-size: 0.98rem;
    margin-bottom: 6px;
}
.forf-dispute-text {
    font-size: 0.88rem;
    color: #4a5870;
    line-height: 1.55;
    font-style: italic;
    background: #ffffff;
    border-left: 3px solid #c2c9d4;
    padding: 8px 12px;
    border-radius: 3px;
}
.forf-controls .btn {
    margin-top: 20px;
    margin-right: 10px;
    border-radius: 4px;
    font-weight: 700;
    letter-spacing: 0.02em;
    padding: 10px 26px;
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.forf-controls .btn-primary {
    background: #14233f;
    border-color: #14233f;
    color: #ffffff;
}
.forf-controls .btn-primary:hover {
    background: #1f3358;
    border-color: #1f3358;
}
.forf-controls .btn-outline-secondary {
    color: #4a5870;
    border-color: #c2c9d4;
    background: #ffffff;
}
.forf-controls .btn-outline-secondary:hover {
    background: #eef1f5;
    color: #14233f;
    border-color: #aab3c1;
}
.forf-feedback {
    background: #14233f;
    color: #f3f5f8;
    border-radius: 6px;
    border-left: 5px solid #b08a3e;
    padding: 20px 26px;
    margin-bottom: 22px;
}
.forf-feedback h3 {
    margin: 0 0 10px 0;
    font-size: 1.05rem;
    color: #d8be83;
    font-weight: 700;
}
.forf-feedback #feedbackText {
    font-size: 0.95rem;
    line-height: 1.65;
    color: #e6e9ef;
}
.forf-history-wrap, .forf-chart-wrap {
    background: #ffffff;
    border: 1px solid #d4dae3;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.forf-history-wrap h3 {
    margin: 0 0 14px 0;
    font-size: 1.05rem;
    color: #14233f;
    font-weight: 700;
}
#usfHistoryTable { width: 100%; }
#usfHistoryTable thead th {
    background: #eef1f5;
    color: #14233f;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    border-bottom: 2px solid #b08a3e;
    padding: 10px 12px;
}
#usfHistoryTable tbody td {
    color: #33425a;
    font-size: 0.9rem;
    padding: 10px 12px;
    border-bottom: 1px solid #eef0f4;
}
.forf-chart-wrap {
    height: 360px;
    position: relative;
}
@media (max-width: 768px) {
    .forf-container { padding: 16px; }
    .forf-header { padding: 20px; }
    .forf-header h1 { font-size: 1.25rem; }
    .forf-controls { padding: 18px 20px; }
    .forf-history-wrap, .forf-chart-wrap { padding: 16px 18px; }
    .forf-status-card .forf-value { font-size: 1.25rem; }
    .forf-value-hero { font-size: 2rem !important; }
    .forf-period-counter .forf-round-name { margin-left: 0; flex-basis: 100%; }
    .forf-bench { grid-template-columns: 1fr; }
}


/* FIX v1.1.0 — completion / debrief screen */
.fof-completion { padding: 10px 6px; text-align: center; }
.fof-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.fof-completion-score { font-size: 20px; color: #0f172a; margin-bottom: 14px; }
.fof-completion-score strong { color: #7c3aed; }
.fof-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.fof-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 110px; }
.fof-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.fof-completion-metric strong { font-size: 16px; color: #0f172a; }
.fof-completion-verdict { max-width: 680px; margin: 0 auto 12px; text-align: left; padding: 12px 16px; background: #f8fafc; border-left: 3px solid #7c3aed; border-radius: 4px; color: #1e293b; font-size: 14px; line-height: 1.5; }
.fof-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.fof-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #f5f3ff; border-left: 3px solid #a78bfa; border-radius: 4px; color: #1e293b; font-size: 13px; }

js:
(function() {
    'use strict';

    class FrictionOrFuelAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Friction or Fuel';
            this.version = '1.1.0';

            // 14-candidate bench. seniority 1-5, cogDiv 1-5 (cognitive/deep diversity),
            // demDiv 1-5 (demographic/visible diversity), load = latent conflict load 0-3,
            // rollRisk = is this a high-diversity hire likely to roll off if disengaged.
            this.BENCH = [
                { id: 'c1',  nameKey: 'cand_c1',  fn: 'fn_lead',     seniority: 5, cogDiv: 2, demDiv: 1, load: 1, rollRisk: false },
                { id: 'c2',  nameKey: 'cand_c2',  fn: 'fn_delivery', seniority: 5, cogDiv: 2, demDiv: 1, load: 2, rollRisk: false },
                { id: 'c3',  nameKey: 'cand_c3',  fn: 'fn_tech',     seniority: 5, cogDiv: 2, demDiv: 2, load: 2, rollRisk: false },
                { id: 'c4',  nameKey: 'cand_c4',  fn: 'fn_arch',     seniority: 4, cogDiv: 3, demDiv: 2, load: 2, rollRisk: false },
                { id: 'c5',  nameKey: 'cand_c5',  fn: 'fn_arch',     seniority: 4, cogDiv: 4, demDiv: 4, load: 2, rollRisk: true  },
                { id: 'c6',  nameKey: 'cand_c6',  fn: 'fn_data',     seniority: 3, cogDiv: 5, demDiv: 4, load: 1, rollRisk: true  },
                { id: 'c7',  nameKey: 'cand_c7',  fn: 'fn_design',   seniority: 3, cogDiv: 5, demDiv: 3, load: 1, rollRisk: true  },
                { id: 'c8',  nameKey: 'cand_c8',  fn: 'fn_change',   seniority: 3, cogDiv: 4, demDiv: 5, load: 1, rollRisk: true  },
                { id: 'c9',  nameKey: 'cand_c9',  fn: 'fn_pmo',      seniority: 4, cogDiv: 2, demDiv: 2, load: 1, rollRisk: false },
                { id: 'c10', nameKey: 'cand_c10', fn: 'fn_risk',     seniority: 4, cogDiv: 2, demDiv: 1, load: 1, rollRisk: false },
                { id: 'c11', nameKey: 'cand_c11', fn: 'fn_data',     seniority: 2, cogDiv: 5, demDiv: 5, load: 1, rollRisk: true  },
                { id: 'c12', nameKey: 'cand_c12', fn: 'fn_design',   seniority: 2, cogDiv: 4, demDiv: 4, load: 1, rollRisk: true  },
                { id: 'c13', nameKey: 'cand_c13', fn: 'fn_client',   seniority: 3, cogDiv: 3, demDiv: 3, load: 1, rollRisk: false },
                { id: 'c14', nameKey: 'cand_c14', fn: 'fn_tech',     seniority: 2, cogDiv: 3, demDiv: 4, load: 1, rollRisk: true  }
            ];

            // Correct diagnosis for the three disputes.
            this.CORRECT_TYPE = { A: 'task', B: 'process', C: 'relationship' };
            // Ideal intensity reading per dispute (task moderate = fuel; relationship high = burns).
            this.IDEAL_INTENSITY = { A: 3, B: 3, C: 5 };
            // Correct intervention per conflict type.
            this.CORRECT_INTERVENTION = { task: 'debate', process: 'roles', relationship: 'mediate' };
            this.ALT_OK_INTERVENTION = { relationship: 'separate' };
            this.ATTN_BUDGET = 6;
        }

        // ---------- lifecycle ----------
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    pod: [],
                    podCount: 0,
                    diversityScore: 0,
                    experienceScore: 0,
                    latentLoad: 0,
                    rollRiskCount: 0,
                    hypothesis: null,
                    diagnosis: { A: null, B: null, C: null },
                    intensity: { A: 0, B: 0, C: 0 },
                    diagnosisAccuracy: 0,
                    interventions: { A: null, B: null, C: null },
                    attnSpent: 0,
                    decisionQuality: 0,
                    onTimeProb: 0,
                    retention: null,
                    pitch: null,
                    confidence: 0,
                    roi: 0,
                    roiHistory: [],
                    decisionHistory: [],
                    ontimeHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 50);
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim.state;
            this._updateBriefing(state);
            var round = state.currentPeriod || 1;

            if (round === 1) {
                var picked = this._readPod();
                if (picked.length !== 8) {
                    sim.uiManager.showNotification(sim.t('warn_pod_size'), 'warning');
                    return false;
                }
                var hyp = (document.getElementById('hypothesisInput') || {}).value;
                if (!hyp) {
                    sim.uiManager.showNotification(sim.t('warn_hypothesis'), 'warning');
                    return false;
                }
                decisions.pod = picked;
                decisions.hypothesis = hyp;
                return true;
            }

            if (round === 2) {
                var tA = (document.getElementById('typeAInput') || {}).value;
                var tB = (document.getElementById('typeBInput') || {}).value;
                var tC = (document.getElementById('typeCInput') || {}).value;
                if (!tA || !tB || !tC) {
                    sim.uiManager.showNotification(sim.t('warn_classify'), 'warning');
                    return false;
                }
                var iA = parseInt((document.getElementById('intensityAInput') || {}).value, 10);
                var iB = parseInt((document.getElementById('intensityBInput') || {}).value, 10);
                var iC = parseInt((document.getElementById('intensityCInput') || {}).value, 10);
                if (![iA, iB, iC].every(function(v) { return Number.isFinite(v) && v >= 1 && v <= 5; })) {
                    sim.uiManager.showNotification(sim.t('warn_intensity'), 'warning');
                    return false;
                }
                decisions.typeA = tA; decisions.typeB = tB; decisions.typeC = tC;
                decisions.intA = iA; decisions.intB = iB; decisions.intC = iC;
                return true;
            }

            if (round === 3) {
                var vA = (document.getElementById('interventionAInput') || {}).value;
                var vB = (document.getElementById('interventionBInput') || {}).value;
                var vC = (document.getElementById('interventionCInput') || {}).value;
                if (!vA || !vB || !vC) {
                    sim.uiManager.showNotification(sim.t('warn_intervention'), 'warning');
                    return false;
                }
                var pA = parseInt((document.getElementById('pointsAInput') || {}).value, 10);
                var pB = parseInt((document.getElementById('pointsBInput') || {}).value, 10);
                var pC = parseInt((document.getElementById('pointsCInput') || {}).value, 10);
                if (![pA, pB, pC].every(function(v) { return Number.isFinite(v) && v >= 0 && v <= 3; })) {
                    sim.uiManager.showNotification(sim.t('warn_points_range'), 'warning');
                    return false;
                }
                if (pA + pB + pC > this.ATTN_BUDGET) {
                    sim.uiManager.showNotification(sim.t('warn_budget'), 'warning');
                    return false;
                }
                decisions.ivA = vA; decisions.ivB = vB; decisions.ivC = vC;
                decisions.ptA = pA; decisions.ptB = pB; decisions.ptC = pC;
                return true;
            }

            if (round === 4) {
                var ret = (document.getElementById('retentionInput') || {}).value;
                var pit = (document.getElementById('pitchInput') || {}).value;
                var conf = parseInt((document.getElementById('confidenceInput') || {}).value, 10);
                if (!ret) {
                    sim.uiManager.showNotification(sim.t('warn_retention'), 'warning');
                    return false;
                }
                if (!pit) {
                    sim.uiManager.showNotification(sim.t('warn_pitch'), 'warning');
                    return false;
                }
                if (!Number.isFinite(conf) || conf < 1 || conf > 5) {
                    sim.uiManager.showNotification(sim.t('warn_confidence'), 'warning');
                    return false;
                }
                decisions.retention = ret;
                decisions.pitch = pit;
                decisions.confidence = conf;
                return true;
            }

            return true;
        }

        calculateResults(state) {
            var r = this._calculateResultsCore(state) || {};
            // v1.1.0 FIX A — surface the headline metric on the paths the reporting/grading
            // layer reads (express_resolveDomainScore -> performance.overallScore / domainState.score;
            // trend chart -> results.score/overallScore). roi (0-100) once available, else the
            // running decisionQuality / roundScore. No domain math changed.
            var headline;
            if (typeof r.roi === 'number' && r.roi > 0) headline = r.roi;
            else if (typeof r.decisionQuality === 'number' && r.decisionQuality > 0) headline = r.decisionQuality;
            else if (typeof r.roundScore === 'number') headline = r.roundScore;
            else headline = 0;
            var sc = Math.max(0, Math.min(100, Math.round(headline)));
            var gk = sc >= 70 ? 'grade_high' : sc >= 50 ? 'grade_mid' : 'grade_low';
            state.domainState.score = sc;
            state.domainState.performance = { overallScore: sc, grade: this._t(gk) };
            r.score = sc;
            r.overallScore = sc;
            return r;
        }

        _calculateResultsCore(state) {
            var d = state.decisions;
            var round = state.currentPeriod;
            var ds = state.domainState;
            var fb = [];

            if (round === 1) {
                var podObjs = this._podObjects(d.pod);
                var n = podObjs.length || 1;
                var avgCog = this._avg(podObjs, 'cogDiv');
                var avgDem = this._avg(podObjs, 'demDiv');
                var avgSen = this._avg(podObjs, 'seniority');
                var load = podObjs.reduce(function(s, c) { return s + c.load; }, 0);
                var rollers = podObjs.filter(function(c) { return c.rollRisk; }).length;

                ds.pod = d.pod;
                ds.podCount = podObjs.length;
                // Cognitive diversity is the dividend driver (1-5 -> 0-100), weighted to cognitive.
                ds.diversityScore = Math.round(((avgCog * 0.7 + avgDem * 0.3) - 1) / 4 * 100);
                ds.experienceScore = Math.round((avgSen - 1) / 4 * 100);
                ds.latentLoad = load;
                ds.rollRiskCount = rollers;
                ds.hypothesis = d.hypothesis;

                // The dividend lives in cognitive diversity, but seniority must clear a floor
                // (least-experienced diverse pod cannot deliver a bank programme).
                var roundScore = ds.diversityScore;
                if (ds.experienceScore < 45) {
                    roundScore -= (45 - ds.experienceScore) * 0.8;
                    fb.push(sim_t('r1_fb_underexp'));
                }
                if (ds.diversityScore < 45) {
                    // Safe homogeneous pod: comfortable, forfeits the dividend the firm sold.
                    roundScore -= 18;
                    fb.push(sim_t('r1_fb_safe'));
                } else if (ds.diversityScore >= 60 && ds.experienceScore >= 50) {
                    fb.push(sim_t('r1_fb_balanced'));
                } else {
                    fb.push(sim_t('r1_fb_ok'));
                }
                // An honest hypothesis (expecting relationship friction on a diverse pod) earns a little.
                if (d.hypothesis === 'relationship') {
                    roundScore += 6;
                    fb.push(sim_t('r1_fb_hyp_good'));
                } else if (d.hypothesis === 'task') {
                    roundScore += 2;
                }
                roundScore = this._clamp(roundScore, 0, 100);

                ds.decisionQuality = Math.round(roundScore);
                ds.roiHistory.push(0);
                ds.decisionHistory.push(ds.decisionQuality);
                ds.ontimeHistory.push(0);

                this._afterRound(state, ds);
                return {
                    period: round,
                    roundScore: Math.round(roundScore),
                    diversity: ds.diversityScore,
                    experience: ds.experienceScore,
                    decisionQuality: ds.decisionQuality,
                    onTimeProb: 0,
                    roi: 0,
                    feedback: fb.join(' '),
                    label: this._t('r1_label')
                };
            }

            if (round === 2) {
                ds.diagnosis = { A: d.typeA, B: d.typeB, C: d.typeC };
                ds.intensity = { A: d.intA, B: d.intB, C: d.intC };
                var correct = 0;
                var keys = ['A', 'B', 'C'];
                for (var i = 0; i < keys.length; i++) {
                    if (ds.diagnosis[keys[i]] === this.CORRECT_TYPE[keys[i]]) correct++;
                }
                ds.diagnosisAccuracy = Math.round(correct / 3 * 100);

                // The signature trap: calling the operating-model dispute a relationship clash.
                if (d.typeA === 'relationship') fb.push(sim_t('r2_fb_misA'));
                else if (d.typeA === 'task') fb.push(sim_t('r2_fb_okA'));
                if (d.typeB !== 'process') fb.push(sim_t('r2_fb_misB'));
                if (d.typeC !== 'relationship') fb.push(sim_t('r2_fb_misC'));
                else fb.push(sim_t('r2_fb_okC'));

                // Intensity reading bonus: recognise relationship conflict is severe.
                var intBonus = 0;
                if (d.typeC === 'relationship' && d.intC >= 4) intBonus += 6;
                if (d.typeA === 'task' && d.intA >= 2 && d.intA <= 4) intBonus += 4;

                var diagScore = this._clamp(ds.diagnosisAccuracy + intBonus, 0, 100);
                // Decision quality drifts toward diagnosis accuracy (you cannot fix what you misread).
                ds.decisionQuality = Math.round((ds.decisionQuality * 0.4) + (diagScore * 0.6));
                if (correct === 3) fb.push(sim_t('r2_fb_clean'));

                ds.roiHistory.push(0);
                ds.decisionHistory.push(ds.decisionQuality);
                ds.ontimeHistory.push(0);

                this._afterRound(state, ds);
                return {
                    period: round,
                    roundScore: diagScore,
                    diagnosisAccuracy: ds.diagnosisAccuracy,
                    decisionQuality: ds.decisionQuality,
                    onTimeProb: 0,
                    roi: 0,
                    feedback: fb.join(' '),
                    label: this._t('r2_label')
                };
            }

            if (round === 3) {
                ds.interventions = { A: d.ivA, B: d.ivB, C: d.ivC };
                ds.attnSpent = d.ptA + d.ptB + d.ptC;

                // Score each intervention against the TRUE conflict type (not what they guessed).
                var resA = this._scoreIntervention('A', d.ivA, d.ptA, fb);
                var resB = this._scoreIntervention('B', d.ivB, d.ptB, fb);
                var resC = this._scoreIntervention('C', d.ivC, d.ptC, fb);
                var ivScore = this._clamp((resA + resB + resC) / 3, 0, 100);

                // On-time delivery probability is driven mostly by handling relationship conflict (C).
                var ontime = 50;
                ontime += (resC - 50) * 0.5;          // relationship handling dominates schedule risk
                ontime += (resB - 50) * 0.2;          // process / decision rights
                ontime += (ds.decisionQuality - 50) * 0.2;
                ds.onTimeProb = Math.round(this._clamp(ontime, 5, 95));

                // Decision quality: protecting task debate (A) lifts it; smothering it sinks it.
                var dqDelta = (resA - 50) * 0.5 + (resB - 50) * 0.2;
                ds.decisionQuality = Math.round(this._clamp(ds.decisionQuality + dqDelta, 0, 100));

                if (ds.attnSpent < this.ATTN_BUDGET) fb.push(sim_t('r3_fb_underspend'));

                ds.roiHistory.push(0);
                ds.decisionHistory.push(ds.decisionQuality);
                ds.ontimeHistory.push(ds.onTimeProb);

                this._afterRound(state, ds);
                return {
                    period: round,
                    roundScore: Math.round(ivScore),
                    decisionQuality: ds.decisionQuality,
                    onTimeProb: ds.onTimeProb,
                    roi: 0,
                    feedback: fb.join(' '),
                    label: this._t('r3_label')
                };
            }

            if (round === 4) {
                ds.retention = d.retention;
                ds.pitch = d.pitch;
                ds.confidence = d.confidence;

                // Retention: ignoring/replacing the roll-off risks collapses the pod toward the
                // homogeneous team you rejected -> diversity (and the dividend) evaporates.
                var divEff = ds.diversityScore;
                if (d.retention === 'engage') {
                    fb.push(sim_t('r4_fb_engage'));
                    ds.decisionQuality = Math.round(this._clamp(ds.decisionQuality + 6, 0, 100));
                } else if (d.retention === 'incentive') {
                    fb.push(sim_t('r4_fb_incentive'));
                    divEff = Math.round(divEff * 0.85);
                } else if (d.retention === 'ignore') {
                    fb.push(sim_t('r4_fb_ignore'));
                    divEff = Math.round(divEff * 0.55);
                    ds.onTimeProb = Math.round(this._clamp(ds.onTimeProb - 8, 5, 95));
                } else if (d.retention === 'replace') {
                    fb.push(sim_t('r4_fb_replace'));
                    divEff = Math.round(divEff * 0.45);
                }

                // Return on Inclusion = decision quality x on-time, CONDITIONAL on diversity that
                // survived to Day 45. A homogeneous (low-div) team caps the ceiling.
                var dividendFactor = 0.55 + (divEff / 100) * 0.45; // 0.55..1.0
                var baseRoi = (ds.decisionQuality * 0.55 + ds.onTimeProb * 0.45);
                ds.roi = Math.round(this._clamp(baseRoi * dividendFactor, 0, 100));

                // Pitch quality: honest evidence-based framing scores; spin/org-chart framing is
                // exposed by the client sponsor.
                var pitchScore = 50;
                if (d.pitch === 'evidence') { pitchScore = 90; fb.push(sim_t('r4_fb_evidence')); }
                else if (d.pitch === 'diversity') { pitchScore = 45; fb.push(sim_t('r4_fb_diversity')); }
                else if (d.pitch === 'spin') { pitchScore = 25; fb.push(sim_t('r4_fb_spin')); }

                // Calibration: over-claiming when ROI is low is penalised; honest low-confidence
                // when ROI is genuinely low is rewarded.
                var roiTier = ds.roi >= 70 ? 5 : ds.roi >= 55 ? 4 : ds.roi >= 40 ? 3 : ds.roi >= 25 ? 2 : 1;
                var miscalib = Math.abs(d.confidence - roiTier);
                if (miscalib === 0) fb.push(sim_t('r4_fb_calib_good'));
                else if (miscalib >= 2 && d.confidence > roiTier) fb.push(sim_t('r4_fb_overclaim'));

                var roundScore = this._clamp(ds.roi * 0.7 + pitchScore * 0.2 + (5 - miscalib) / 5 * 100 * 0.1, 0, 100);

                ds.roiHistory.push(ds.roi);
                ds.decisionHistory.push(ds.decisionQuality);
                ds.ontimeHistory.push(ds.onTimeProb);

                this._afterRound(state, ds);
                return {
                    period: round,
                    roundScore: Math.round(roundScore),
                    decisionQuality: ds.decisionQuality,
                    onTimeProb: ds.onTimeProb,
                    roi: ds.roi,
                    feedback: fb.join(' '),
                    label: this._t('r4_label')
                };
            }

            this._afterRound(state, ds);
            return { period: round, roundScore: 0, feedback: '', roi: ds.roi };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('diversityDisplay', 'domainState.diversityScore', function(v) { return (v || 0) + ' / 100'; });
            uiManager.bind('decisionDisplay', 'domainState.decisionQuality', function(v) { return (v || 0) + ' / 100'; });
            uiManager.bind('ontimeDisplay', 'domainState.onTimeProb', function(v) { return (v || 0) + '%'; });
            uiManager.bind('roiDisplay', 'domainState.roi', function(v) { return (v || 0) + ' / 100'; });
        }

