        // ---------- end-of-game summary ----------
        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var roi = (summary.roi != null) ? Math.round(summary.roi) : 0;
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="fof-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var metrics = ''
                + metric(t('comp_roi_label'), roi + '/100')
                + metric(t('comp_dq_label'), (summary.decisionQuality != null ? Math.round(summary.decisionQuality) : '-'))
                + metric(t('comp_ontime_label'), (summary.onTimeProb != null ? Math.round(summary.onTimeProb) + '%' : '-'));
            return ''
                + '<div class="fof-completion">'
                +   '<div class="fof-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="fof-completion-score">' + t('comp_roi_label') + ': <strong>' + roi + '</strong> / 100</div>'
                +   '<div class="fof-completion-metrics">' + metrics + '</div>'
                +   (summary.verdict ? '<div class="fof-completion-verdict">' + summary.verdict + '</div>' : '')
                +   (items ? '<ul class="fof-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = (history[history.length - 1] || {}).results || {};
            var roi = last.roi || 0;
            var dq = last.decisionQuality || 0;
            var ontime = last.onTimeProb || 0;

            var verdict;
            if (roi >= 70) verdict = this._t('end_verdict_high');
            else if (roi >= 50) verdict = this._t('end_verdict_mid');
            else verdict = this._t('end_verdict_low');

            var insights = [];
            var r1 = (history[0] || {}).results || {};
            var r2 = (history[1] || {}).results || {};
            if ((r1.diversity || 0) < 45) insights.push(this._t('end_ins_safe'));
            if ((r2.diagnosisAccuracy || 0) < 67) insights.push(this._t('end_ins_misdiag'));
            if (ontime < 50) insights.push(this._t('end_ins_ontime'));
            if (roi >= 70) insights.push(this._t('end_ins_dividend'));
            if (!insights.length) insights.push(this._t('end_ins_solid'));

            return {
                roi: roi,
                decisionQuality: dq,
                onTimeProb: ontime,
                verdict: verdict,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results && results.feedback) return results.feedback;
            return null;
        }

        getPresets() { return null; }

        // ---------- helpers ----------
        _t(key) {
            try {
                return (window.mySimulation && window.mySimulation.t)
                    ? window.mySimulation.t(key)
                    : key;
            } catch (e) { return key; }
        }

        _clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

        _avg(arr, prop) {
            if (!arr.length) return 0;
            var s = 0;
            for (var i = 0; i < arr.length; i++) s += arr[i][prop];
            return s / arr.length;
        }

        _podObjects(ids) {
            var out = [];
            for (var i = 0; i < this.BENCH.length; i++) {
                if (ids.indexOf(this.BENCH[i].id) !== -1) out.push(this.BENCH[i]);
            }
            return out;
        }

        _readPod() {
            var picked = [];
            var boxes = document.querySelectorAll('.forf-cand input[type="checkbox"]');
            for (var i = 0; i < boxes.length; i++) {
                if (boxes[i].checked) picked.push(boxes[i].value);
            }
            return picked;
        }

        // Score one intervention against the TRUE conflict type at that slot.
        _scoreIntervention(slot, intervention, points, fb) {
            var trueType = this.CORRECT_TYPE[slot];
            var ideal = this.CORRECT_INTERVENTION[trueType];
            var alt = this.ALT_OK_INTERVENTION[trueType];
            var base;

            if (intervention === ideal) base = 95;
            else if (alt && intervention === alt) base = 80;
            else if (intervention === 'ignore') base = trueType === 'relationship' ? 5 : 35;
            else if (trueType === 'task' && (intervention === 'mediate' || intervention === 'separate')) base = 20; // smother the debate
            else if (trueType === 'relationship' && intervention === 'debate') base = 25; // romanticising friction
            else base = 45;

            // Attention scaling: relationship conflict needs investment; ignoring under-resources it.
            var weight = points / 3; // 0..1
            var floor = trueType === 'relationship' ? 0.4 : 0.55;
            var effective = base * (floor + (1 - floor) * weight);

            // Targeted facilitator lines.
            if (slot === 'A' && (intervention === 'mediate' || intervention === 'separate')) fb.push(sim_t('r3_fb_smotherA'));
            if (slot === 'C' && intervention === 'debate') fb.push(sim_t('r3_fb_runC'));
            if (slot === 'C' && intervention === 'ignore') fb.push(sim_t('r3_fb_runC'));
            if (slot === 'C' && (intervention === 'mediate' || intervention === 'separate') && points >= 2) fb.push(sim_t('r3_fb_goodC'));
            if (slot === 'B' && intervention === 'roles') fb.push(sim_t('r3_fb_goodB'));
            if (slot === 'A' && intervention === 'debate') fb.push(sim_t('r3_fb_goodA'));

            return effective;
        }

        _afterRound(state, ds) {
            var self = this;
            setTimeout(function() {
                var next = { currentPeriod: (state.currentPeriod || 1) + 1, domainState: ds };
                self._updateBriefing(next);
                var fw = document.getElementById('feedbackWrap');
                var ft = document.getElementById('feedbackText');
                if (fw && ft) {
                    var hist = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.history) || [];
                    var lastFb = '';
                    if (hist.length) { var r = hist[hist.length - 1].results || {}; lastFb = r.feedback || ''; }
                    if (lastFb) { ft.innerHTML = lastFb; fw.style.display = 'block'; }
                }
            }, 500);
        }

        // ---------- bench rendering ----------
        _renderBench() {
            var list = document.getElementById('benchList');
            if (!list || list.dataset.rendered === '1') return;
            var self = this;
            list.innerHTML = '';
            for (var i = 0; i < this.BENCH.length; i++) {
                var c = this.BENCH[i];
                var wrap = document.createElement('label');
                wrap.className = 'forf-cand';
                wrap.setAttribute('data-cid', c.id);

                var cb = document.createElement('input');
                cb.type = 'checkbox';
                cb.value = c.id;
                cb.addEventListener('change', function() { self._onPodChange(); });

                var body = document.createElement('div');
                body.className = 'forf-cand-body';
                var nm = document.createElement('div');
                nm.className = 'forf-cand-name';
                nm.textContent = this._t(c.nameKey) + ' · ' + this._t(c.fn);
                var meta = document.createElement('div');
                meta.className = 'forf-cand-meta';
                meta.textContent = this._t('meta_sen') + ' ' + c.seniority + '/5 · ' + this._t('meta_cog') + ' ' + c.cogDiv + '/5 · ' + this._t('meta_dem') + ' ' + c.demDiv + '/5';
                var tags = document.createElement('div');
                tags.className = 'forf-cand-tags';
                if (c.seniority >= 4) tags.appendChild(this._tag('forf-tag-sen', this._t('tag_senior')));
                if (c.cogDiv >= 4) tags.appendChild(this._tag('forf-tag-div', this._t('tag_diverse')));
                if (c.load >= 2) tags.appendChild(this._tag('forf-tag-risk', this._t('tag_load')));

                body.appendChild(nm);
                body.appendChild(meta);
                body.appendChild(tags);
                wrap.appendChild(cb);
                wrap.appendChild(body);
                list.appendChild(wrap);
            }
            list.dataset.rendered = '1';
        }

        _tag(cls, text) {
            var s = document.createElement('span');
            s.className = 'forf-tag ' + cls;
            s.textContent = text;
            return s;
        }

        _onPodChange() {
            var picked = this._readPod();
            var cnt = document.getElementById('benchCount');
            var warn = document.getElementById('benchWarn');
            if (cnt) cnt.textContent = picked.length;
            var boxes = document.querySelectorAll('.forf-cand');
            for (var i = 0; i < boxes.length; i++) {
                var box = boxes[i].querySelector('input[type="checkbox"]');
                if (box && box.checked) boxes[i].classList.add('selected');
                else boxes[i].classList.remove('selected');
                if (box && !box.checked && picked.length >= 8) box.disabled = true;
                else if (box) box.disabled = false;
            }
            if (warn) warn.textContent = picked.length === 8 ? '' : this._t('warn_pod_size');
        }

        _bindAttn() {
            var ids = ['pointsAInput', 'pointsBInput', 'pointsCInput'];
            var self = this;
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el && el.dataset.bound !== '1') {
                    el.addEventListener('input', function() { self._onAttnChange(); });
                    el.dataset.bound = '1';
                }
            }
            this._onAttnChange();
        }

        _onAttnChange() {
            var a = parseInt((document.getElementById('pointsAInput') || {}).value, 10) || 0;
            var b = parseInt((document.getElementById('pointsBInput') || {}).value, 10) || 0;
            var c = parseInt((document.getElementById('pointsCInput') || {}).value, 10) || 0;
            var total = a + b + c;
            var sp = document.getElementById('attnSpent');
            var warn = document.getElementById('attnWarn');
            if (sp) sp.textContent = total;
            if (warn) warn.textContent = total > this.ATTN_BUDGET ? this._t('warn_budget') : '';
        }

        _updateBriefing(state) {
            var round = (state && state.currentPeriod) || 1;
            if (round > 4) round = 4;
            if (round < 1) round = 1;

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var nameEl = document.getElementById('roundName');

            if (titleEl) titleEl.textContent = this._t('round' + round + '_title');
            if (textEl) textEl.innerHTML = this._t('round' + round + '_text');
            if (nameEl) nameEl.textContent = this._t('round' + round + '_title');

            for (var i = 1; i <= 4; i++) {
                var panel = document.getElementById('round' + i + 'Controls');
                if (panel) panel.style.display = (i === round) ? 'block' : 'none';
            }

            // Inject dispute transcript text (round 2).
            this._setDisputeTexts();

            if (round === 1) this._renderBench();
            if (round === 3) this._bindAttn();
        }

        _setDisputeTexts() {
            var map = { dispute_a_text: this._t('dispute_a_text'), dispute_b_text: this._t('dispute_b_text'), dispute_c_text: this._t('dispute_c_text') };
            var nodes = document.querySelectorAll('[data-i18n="dispute_a_text"],[data-i18n="dispute_b_text"],[data-i18n="dispute_c_text"]');
            for (var i = 0; i < nodes.length; i++) {
                var k = nodes[i].getAttribute('data-i18n');
                if (map[k]) nodes[i].textContent = map[k];
            }
        }

